import{_ as o,a0 as p,w as n,s as u,ao as i,I as r,x as e,a1 as d,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何修復 apt-get update 無法添加新的 CD-ROM 的錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"如何修復 apt-get update 無法添加新的 CD-ROM 的錯誤 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修復 apt-get update 無法添加新的 CD-ROM 的錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修復 apt-get update 無法添加新的 CD-ROM 的錯誤 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150227 How To Fix--Failed to fetch cdrom apt-get update cannot be used to add new CD-ROMs","title":"如何修復 apt-get update 無法添加新的 CD-ROM 的錯誤","tag":"201505","desc":""},"relativePath":"201505/20150227 How To Fix--Failed to fetch cdrom apt-get update cannot be used to add new CD-ROMs.md","filePath":"[post].md"}'),m={name:"201505/20150227 How To Fix--Failed to fetch cdrom apt-get update cannot be used to add new CD-ROMs.md"};function l(c,t,f,g,b,C){const a=p("Link");return n(),u("div",null,[t[16]||(t[16]=i(`<h1 id="如何修復-apt-get-update-無法添加新的-cd-rom-的錯誤" tabindex="-1">如何修復 apt-get update 無法添加新的 CD-ROM 的錯誤 <a class="header-anchor" href="#如何修復-apt-get-update-無法添加新的-cd-rom-的錯誤" aria-label="Permalink to “如何修復 apt-get update 無法添加新的 CD-ROM 的錯誤”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/12/elementary_OS_Freya.jpg" alt=""></p><p>這些天我正在體驗Elementary OS Freya，在這期間，我遇到了一個非常常見的更新錯誤：<strong>Failed to fetch cdrom Please use apt-cdrom to make this CD-ROM recognized by APT. apt-get update cannot be used to add new CD-ROMs</strong>。完整的錯誤在運行apt-get update後看上去像這樣：</p><blockquote><p>W: Failed to fetch cdrom://elementary OS 0.3 <em>Freya</em> – Daily amd64 (20150208)/dists/trusty/main/binary-amd64/Packages Please use apt-cdrom to make this CD-ROM recognized by APT. apt-get update cannot be used to add new CD-ROMs</p><p>W: Failed to fetch cdrom://elementary OS 0.3 <em>Freya</em> – Daily amd64 (20150208)/dists/trusty/restricted/binary-amd64/Packages Please use apt-cdrom to make this CD-ROM recognized by APT. apt-get update cannot be used to add new CD-ROMs</p><p>E: Some index files failed to download. They have been ignored, or old ones used instead.</p></blockquote><p>本篇中，我們會了解如何修復這個錯誤。</p><h3 id="修復apt-get-update無法添加新的cd-rom的錯誤" tabindex="-1">修復apt-get update無法添加新的CD-ROM的錯誤 <a class="header-anchor" href="#修復apt-get-update無法添加新的cd-rom的錯誤" aria-label="Permalink to “修復apt-get update無法添加新的CD-ROM的錯誤”">​</a></h3><p>這個錯誤的原因是cdrom已經被包含在源之中。要修復這個問題，我們需要將它從軟件源中移除。</p><p>在Ubuntu中，找到“軟件與更新”：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/08/Software_Update_Ubuntu.jpeg" alt=""></p><p>在Ubuntu Software的第一個標籤中，找到cdrom，如果它是勾選的，那麼取消勾選。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/CDROM_Error_Update_Software_Sources.jpeg" alt=""></p><p>關閉軟件源並再次運行更新。現在應該可以用了。</p><h3 id="進一步故障排除" tabindex="-1">進一步故障排除： <a class="header-anchor" href="#進一步故障排除" aria-label="Permalink to “進一步故障排除：”">​</a></h3><p>上面描述的方法已經修復了這個<strong>apt-get update cannot be used to add new CD-ROMs</strong>錯誤。但是這個方法對我無效，因為cdrom的選項這時是灰色的，因為我使用的live版本。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/CDROM_Update_Error.png" alt=""></p><p>現在要修復我們的問題了，我們是要採用命令列路線。打開終端並查看軟件源中包含了哪些源：</p><pre><code>cat /etc/apt/sources.list
</code></pre><p>我的輸出是下面這樣：</p><pre><code>deb cdrom:[elementary OS 0.3 _Freya_ – Daily amd64 (20150208)]/ trusty main restricted
deb http://archive.ubuntu.com/ubuntu/ trusty main restricted universe multiverse
deb-src http://archive.ubuntu.com/ubuntu/ trusty main restricted universe multiverse
deb http://security.ubuntu.com/ubuntu/ trusty-security main restricted universe multiverse
deb-src http://security.ubuntu.com/ubuntu/ trusty-security main restricted universe multiverse
deb http://archive.ubuntu.com/ubuntu/ trusty-updates main restricted universe multiverse
deb-src http://archive.ubuntu.com/ubuntu/ trusty-updates main restricted universe multiverse
</code></pre><p>在上面的第一行中。它包含了cdrom。我們需要用‘#’來註釋掉這行：</p><pre><code>#deb cdrom:[elementary OS 0.3 _Freya_ – Daily amd64 (20150208)]/ trusty main restricted
</code></pre><p>要用下面的命令來：</p><pre><code>sudo gedit /etc/apt/sources.list
</code></pre>`,23)),r("p",null,[t[1]||(t[1]=e("在你編輯完軟件源後，再次運行apt-get update。“apt-get update cannot be used to add new CD-ROMs”這個錯誤應該已經修復了。如果你還遇到其他的問題，看一下這篇收集了大部分",-1)),d(a,{href:"http://itsfoss.com/fix-update-errors-ubuntu-1404/"},{default:s(()=>[...t[0]||(t[0]=[e("Ubuntu常見更新錯誤修復",-1)])]),_:1}),t[2]||(t[2]=e("的文章。",-1))]),t[17]||(t[17]=r("p",null,"我希望這篇教程對你有用。如果你還有其他的問題和建議，請在下面留言。",-1)),t[18]||(t[18]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),d(a,{href:"http://itsfoss.com/fix-failed-fetch-cdrom-aptget-update-add-cdroms/"},{default:s(()=>[...t[3]||(t[3]=[e("http://itsfoss.com/fix-failed-fetch-cdrom-aptget-update-add-cdroms/",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("作者：",-1)),d(a,{href:"http://itsfoss.com/author/abhishek/"},{default:s(()=>[...t[5]||(t[5]=[e("Abhishek",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),d(a,{href:"https://github.com/geekpi"},{default:s(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),d(a,{href:"https://github.com/wxy"},{default:s(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=e("本文由 ",-1)),d(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),d(a,{href:"http://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const T=o(m,[["render",l]]);export{D as __pageData,T as default};
